    or Combined matches regex @"(?i)(\$|%24)(\{|%7b)[^}]*(jndi|lower:|upper:|env:|sys:|date:|::-)"
| project TimeGenerated, Computer, sSiteName, cIP, csMethod, csUriStem, csUriQuery, csUserAgent, scStatus
| order by TimeGenerated desc

